import{_ as t,o as a,c as e,ag as i}from"./chunks/framework.DXGyWiRo.js";const k=JSON.parse('{"title":"Custom 框架","description":"","frontmatter":{},"headers":[],"relativePath":"zh/framework/custom.md","filePath":"zh/framework/custom.md","lastUpdated":1785990345000}'),o={name:"zh/framework/custom.md"};function d(p,s,r,n,h,l){return a(),e("div",null,[...s[0]||(s[0]=[i(`<h1 id="custom-框架" tabindex="-1">Custom 框架 <a class="header-anchor" href="#custom-框架" aria-label="Permalink to &quot;Custom 框架&quot;">​</a></h1><p>当项目没有使用 EasyYapi 内置的框架识别器时，可以使用 <strong>Custom</strong> 框架通过配置规则描述项目自己的 API 约定。</p><p>与 Spring、JAX-RS、Feign 和 gRPC 支持不同，Custom 不包含固定的注解识别逻辑。类识别、方法识别、HTTP 方法、路径和参数绑定全部由 <code>custom.*</code> 规则决定。规则生成标准 API endpoint 后，所有已启用的导出渠道（包括 YApi）都可以直接使用这些接口。</p><h2 id="启用-custom" tabindex="-1">启用 Custom <a class="header-anchor" href="#启用-custom" aria-label="Permalink to &quot;启用 Custom&quot;">​</a></h2><p>Custom 默认关闭。打开 <strong>Settings</strong> &gt; <strong>Other Settings</strong> &gt; <strong>EasyApi</strong> &gt; <strong>Features</strong>，在 <strong>Framework Support</strong> 中启用 <code>custom</code>，然后在项目级或全局 <code>.easyapi/*.rules</code> 文件中添加规则。</p><p>Custom 的行标记也默认关闭。如果希望为规则识别出的类显示编辑器行标记，请打开 Custom 框架设置并启用 <strong>line marker for Custom API classes</strong>。</p><h2 id="核心规则" tabindex="-1">核心规则 <a class="header-anchor" href="#核心规则" aria-label="Permalink to &quot;核心规则&quot;">​</a></h2><table tabindex="0"><thead><tr><th>规则</th><th>用途</th></tr></thead><tbody><tr><td><code>custom.class.is.api</code></td><td>识别 API 类</td></tr><tr><td><code>custom.method.is.api</code></td><td>识别接口方法</td></tr><tr><td><code>custom.http.method</code></td><td>提供 HTTP 方法</td></tr><tr><td><code>custom.path</code></td><td>提供类路径或方法路径</td></tr><tr><td><code>custom.param.as.json.body</code></td><td>将参数绑定为 JSON 请求体</td></tr><tr><td><code>custom.param.as.form.body</code></td><td>将参数绑定为表单字段</td></tr><tr><td><code>custom.param.as.path.var</code></td><td>将参数绑定为路径变量</td></tr><tr><td><code>custom.param.as.cookie</code></td><td>将参数绑定为 Cookie</td></tr><tr><td><code>custom.param.name</code></td><td>覆盖 query 或 form 参数名</td></tr><tr><td><code>custom.param.header</code> / <code>custom.param.cookie</code></td><td>提供 header 或 Cookie 名称</td></tr></tbody></table><p>对于不需要精细分类的参数，可以使用 <code>param.http.type</code> 设置 <code>query</code>、<code>path</code>、<code>header</code>、<code>cookie</code>、<code>form</code> 或 <code>body</code>。更具体的 <code>custom.param.as.*</code> 分类规则优先级更高。</p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><p>下面是一个使用自定义注解的项目的起始示例。请根据项目实际约定替换注解名称和路径：</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">custom.class.is.api</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=groovy:it.hasAnn(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;com.example.ApiController&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">custom.method.is.api</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=groovy:it.hasAnn(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;com.example.Api&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">custom.http.method</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=groovy:it.ann(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;com.example.Api&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)?.value() ?: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;GET&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">custom.path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=groovy:it.ann(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;com.example.Path&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)?.value() ?: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">custom.param.as.json.body</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=groovy:it.hasAnn(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;com.example.JsonBody&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">custom.param.as.path.var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=groovy:it.hasAnn(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;com.example.PathVariable&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>如果没有规则提供 HTTP 方法，解析器会依次回退到 <code>method.default.http.method</code>，最后使用 <code>POST</code>。最终路径会组合类路径、方法路径、<code>class.prefix.path</code> 和 <code>endpoint.prefix.path</code>，并规范化重复的斜杠。</p><h2 id="生命周期钩子" tabindex="-1">生命周期钩子 <a class="header-anchor" href="#生命周期钩子" aria-label="Permalink to &quot;生命周期钩子&quot;">​</a></h2><p>Custom 还提供只在 Custom 提取过程中执行的框架级钩子：</p><ul><li><code>custom.class.parse.before</code> / <code>custom.class.parse.after</code></li><li><code>custom.method.parse.before</code> / <code>custom.method.parse.after</code></li><li><code>custom.export.after</code></li></ul><p>通用的 API 解析和导出钩子仍然可用。</p><h2 id="从通用导出规则迁移" tabindex="-1">从通用导出规则迁移 <a class="header-anchor" href="#从通用导出规则迁移" aria-label="Permalink to &quot;从通用导出规则迁移&quot;">​</a></h2><p>v2 的 <code>mdoc.class.filter</code> 和 <code>mdoc.method.filter</code> 在 v3 重写后不再支持。请改用 Custom 识别器：</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">custom.class.is.api</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=groovy:it.hasAnn(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;com.example.ApiController&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">custom.method.is.api</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=groovy:it.hasAnn(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;com.example.Api&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>详见<a href="/zh/settings/config-rule">配置规则</a>和<a href="/zh/settings/rule-authoring">规则编写</a>。</p>`,21)])])}const m=t(o,[["render",d]]);export{k as __pageData,m as default};
